style.css:
@-moz-document domain("goggle.com") {
body {
        background-color: #FAAFBA !important;
        position: relative;
        overflow: hidden;
    }

    body::before,
    body::after {
        content: "";
        position: absolute;
        background-size: contain;
        background-repeat: no-repeat;
        opacity: 0.6;
        filter: blur(8px);
        pointer-events: none;
    }

    body::before {
        background-image: url("https://unsplash.com");
        width: 300px;
        height: 300px;
        top: -5%;
        left: 10%;
        transform: rotate(-15deg);
    }

    body::after {
        background-image: url("https://unsplash.com");
        width: 400px;
        height: 400px;
        bottom: -5%;
        right: 5%;
        transform: rotate(20deg);
    }
}
